public class SumOfEvenNumbers {
    public static int sumOfEvenNumbers(int n) {
        int sum = 0;
        for (int i = 2; i <= n; i += 2) {
            sum += i;
        }
        return sum;
    }

    public static void main(String[] args) {
        int input = 10;
        System.out.println("Sum of even numbers from 1 to " + input + " is: " + sumOfEvenNumbers(input));
    }
}
